ProjectALife.DialogueShards["scenes_misc_8"] = {
{"exp_raider_bigtitle","power",2,"reg=raider|st=neutral,careful,hostile",{1,"We're supposed to call him Commander now",2,"We're supposed to WHAT?",1,"Keep your voice down, for fuck's sake",2,"Guy couldn't get me to work Saturday, now he's Commander"}},
{"exp_raider_petty_share","power",2,"reg=raider|st=neutral,careful,hostile",{1,"You cut yours bigger - again",2,"Then you cut it next time",1,"And you get first pick - like last time?",2,"Oh, here we fucking go"}},
{"exp_military_letterhome","private_life",2,"reg=military|st=neutral,careful",{1,"Last letter I sent, I told Mom nothing was happening",2,"When was that?",1,"Before all this - I just... that's the last thing she heard from me",2,"You didn't know, neither did I"}},
{"exp_elite_rest_face","private_life",2,"reg=elite|st=neutral,careful",{1,"Can't remember the last time I saw you in a T-shirt",2,"Cookout, burned the burgers",1,"Right, you blamed my grill",2,"Still blame your grill"}},
{"exp_outlaw_realname","private_life",2,"reg=outlaw|st=neutral,careful",{1,"Your mom really called you that?",2,"Yeah, and no, you can't",1,"Wasn't gonna",2,"You were grinning, you were absolutely gonna"}},
{"s13_law_link_down_006","radio",2,"reg=law|role=law_deputy|world=vehicle,window",{1,"Run me a plate - Kentucky, Charlie Victor Nine Four Two",2,"Can't - LINK's been down since the fourth and NCIC with it",1,"So I'm stood here looking at a truck with no way on earth to know whose it is",2,"Knock on the window and ask him, that's police work, Tolliver"}},
{"s13_law_dispatch_alone_015","radio",2,"reg=law|hour=16,5",{1,"Who's on the console tonight?",2,"Nobody, base is on the desk with the speaker up - it squawks, I'll hear it from the hall"}},
{"s13_law_mutual_aid_017","radio",3,"reg=law|tmp=seasoned|world=vehicle",{1,"Muldraugh PD's got two officers and a pickup",2,"West Point's got one, he is sixty-one years old",3,"Rosewood's got a chief and the chief's got pneumonia",1,"That's the mutual aid, fellas, that's the plan we been leaning on all week"}},
{"s13_law_scanner_neighbors_023","radio",2,"reg=law|mood=grim|world=building",{1,"Half this county's got a scanner on the kitchen table",2,"Good, let 'em hear it",1,"They heard Combs call for help eleven minutes, now they know exactly what we are"}},
{"s13_law_radio_discipline_044","radio",2,"reg=law|tmp=veteran",{1,"Keep it to unit, location, what you need, the rest is a favor to whoever's listening",2,"And if nobody's listening?",1,"Then keep it to unit, location, what you need, that's how you find out"}},
{"s13_law_last_call_049","radio",2,"reg=law|mood=sad",{1,"Knox County, Knox 14 - show me out of service at end of shift",2,"Knox 14, copy, ain't no beginning of shift no more, you know that",1,"I know it - say it anyway - show me out of service",2,"Knox 14 out of service at {time} - logged"}},
{"s13_law_ten_codes_053","radio",2,"reg=law|mood=funny",{1,"New fella says 10-4 for everything. 10-4 this, 10-4 that",2,"Let him, it's the only part of the job he's sure about"}},
{"s13_ksp_skip_summer_001","radio",2,"reg=law|role=law_trooper|tmp=seasoned",{1,"Low band skips in July, I've got Dry Ridge clear as a church bell and I cannot raise Elizabethtown",2,"How far's Elizabethtown?",1,"Twenty-two miles, and I'm talking to a man a hundred and some north - that's summer for you"}},
{"s13_ksp_post_quit_002","radio",2,"reg=law|role=law_trooper|mood=grim",{1,"Post 4, Post 4, unit 417 - radio check",1,"Post 4, 417, radio check, any station, any station",2,"417, Knox 11, we hear you, post 4 ain't answered since Sunday dinner",1,"Copy, Knox 11, then I guess I'm the post"}},
{"s13_ksp_i_am_the_post_003","radio",2,"reg=law|role=law_trooper|world=vehicle",{1,"You're relaying for a whole district off the hood of a car?",2,"Off the hood of a car with a notebook and a pencil - sixteen messages in it",1,"Sixteen - who for?",2,"Families, mostly, nobody's ordering anybody to do anything - it's just messages now"}},
{"s13_ksp_teletype_dead_006","radio",2,"reg=law",{1,"Teletype at the post quit mid-line, paper's still hanging out of it",2,"What's it say?",1,"Half of an attempt to locate out of Bullitt County - ends in the middle of a license number"}},
{"s13_ksp_relay_message_017","radio",3,"reg=law|role=law_trooper|mood=warm",{1,"Post 4 relay, anybody with a Riverside connection, message for a Mrs. Pruitt on Halbert Street",2,"Go ahead with the message",1,"From her brother Earl, quote, I'm at the Kelso place with the Tandys, baby's fine, quit driving",3,"I can get that to Halbert Street - give me twenty minutes",1,"Copy, that's eleven of sixteen, five to go and I'll be honest, I'm hoarse"}},
{"s13_ksp_dispatcher_daughter_018","radio",2,"reg=law",{1,"Loretta's girl works the state console up in Frankfort - worked",2,"Worked?",1,"Frankfort's still up, best I can tell, they just won't put a call into a county they call closed"}},
{"s13_ksp_six_units_024","radio",3,"reg=law|mood=grim",{1,"Roll the district. 411",2,"Nothing",1,"417",3,"417's me",1,"422. 429. 434",2,"Nothing, nothing and nothing",1,"Alright - District's two cars, log it that way and don't soften it"}},
{"s13_ksp_out_of_state_025","radio",2,"reg=law|world=water",{1,"I had Indiana on the low band last night - clear as anything",2,"What'd they say?",1,"Asked what our side of the river looked like, I said the bridge is shut and the river works fine"}},
{"s13_ksp_relay_deputy_035","radio",2,"reg=law|world=vehicle",{1,"Knox 11, 417, switch to the car-to-car and I'll take your traffic",2,"417, Knox 11 switching - and thanks, you're the only ears we got",1,"Don't thank me, just talk slow and spell the names"}},
{"s13_ksp_spell_names_036","radio",3,"reg=law",{1,"Spell it for me",2,"C as in Charlie, U, N, D, I, F, F",1,"Cundiff - first name?",3,"Ray - R as in Robert",1,"Got it - Ray Cundiff, Halbert Street, he's on my page two"}},
{"s13_ksp_relay_hours_044","radio",1,"reg=law|role=law_trooper|world=window",{1,"I take traffic at seven in the morning and seven at night - two windows, that's it",1,"Told everybody on the low band, seven and seven, this unit, this county",1,"First night two people called, last night it was nine - word travels without a phone, just slower"}},
{"s13_ksp_kid_on_cb_045","radio",2,"reg=law|mood=warm",{1,"There's a boy on the CB out past March Ridge with a handle I won't repeat",2,"He in trouble?",1,"He's twelve, alone in a house, talking to a state trooper every night at seven - not yet he ain't"}},
{"s13_ksp_signing_off_050","radio",2,"reg=law|mood=warm|world=window",{1,"Post 4 relay, 417, closing the seven o'clock window - nothing further",2,"417, before you go - are you eating?",1,"Say again?",2,"I asked are you eating, it's a question",1,"... Copy - I'm eating. 417 out"}},
{"s13_ksp_hardin12_relay_051","radio",2,"reg=law|mood=sad",{1,"Hardin 12, 417 - you still running?",2,"Half a tank and a bad alternator - go ahead",1,"Nothing official, I wanted to hear a unit number come back at me is all",2,"Hardin 12 is still in service - there - feel better?",1,"Some - yeah"}},
{"s13_ksp_scanner_lady_055","radio",2,"reg=law|mood=funny",{1,"Woman out on Echo Creek Road's been logging every call I make",2,"That bother you?",1,"She's got better handwriting than the post did, I'm thinking about asking her to keep at it"}},
{"s13_ksp_relay_soldier_059","radio",2,"reg=law|hour=4,9|world=road",{1,"Had a Guard sergeant on the low band asking after the sheriff",2,"What'd he want?",1,"Somebody local to tell a family their road closes at first light - didn't want to be the one",2,"So who's saying it?",1,"Me, seven in the morning, on the radio, to whoever's got their ears on"}},
{"s13_ksp_last_window_061","radio",3,"reg=law|mood=warm|world=window",{1,"Post 4 relay, seven o'clock window is open - who's got traffic?",2,"417, this is the Kelso place, we got nothing - we just like hearing it start",3,"Same here, nothing to pass",1,"Copy both, window's open twenty minutes, I'll read the log out loud if nobody's got better"}},
{"s13_wire_battalion_silent_012","radio",2,"reg=military|mood=grim",{1,"Battalion's been off the net since Monday morning",2,"So who's giving us orders?",1,"Nobody, we're eleven days into the last thing a major said into a handset"}},
{"s13_wire_major_last_words_013","radio",2,"reg=military|world=road",{1,"What exactly did he say?",2,"Hold the road at Ekron, don't let anybody through, we'll send relief",1,"Relief",2,"That's the word he used, I wrote it in the log with the time beside it"}},
{"s13_wire_radio_civilian_055","radio",2,"reg=military|world=road",{1,"There's a state trooper on the low band taking messages at seven",2,"So?",1,"So I asked him to tell a family their road closes - somebody local ought to say it, not us"}},
{"s13_sf_one_time_pad_012","radio",2,"reg=elite|role=elite_operator|world=window",{1,"Traffic goes out on the pad, five letter groups, sent twice, then nothing",2,"Who's reading it?",1,"I don't know, I send it at the window anyway - twelve minutes, every third day"}},
{"s13_sf_commo_window_013","radio",2,"reg=elite|mood=grim|world=window,trees",{1,"Window's 0300 to 0312 - Primary, then alternate, then we're done",2,"Nine days of nothing",1,"Ten, and I'll be sat there at 0300 tomorrow with the wire up in a tree"}},
{"s13_sf_hf_wire_014","radio",2,"reg=elite|world=fence,water",{1,"The manpack wants a hundred foot of wire in the air and a decent ground",2,"Where's your ground?",1,"Fence post and a jug of creek water poured on it - ugly, and it works"}},
{"fw_ld4_topics_a_0023","rest",2,"reg=civilian,family,worker,rescue",{1,"I could sleep standing up",2,"You have been",1,"I have?",2,"For about ten minutes, you snored",1,"Sorry",2,"Don't be, it was the first quiet I've had all day"}},
{"fw_ld4_topics_a_0024","rest",2,"reg=civilian,family,worker,rescue",{1,"Don't let me sleep long",2,"How long?",1,"Twenty minutes",2,"Done, I'll wake you",1,"You won't forget?",2,"I won't forget"}},
{"fw_ld4_topics_a_0025","rest",2,"reg=civilian,family,worker,rescue",{1,"My feet are bleeding",2,"Take off your socks",1,"I can't, they're stuck",2,"Pour water on them",1,"...ow, ow, ow, God, that hurts, but thanks"}},
{"fw_ld4_topics_a_0026","rest",2,"reg=civilian,family,worker,rescue",{1,"This is nice",2,"What?",1,"Just sitting",2,"Yeah, we should do it more often",1,"We should have done it before all this"}},
{"fw_ld4_topics_a_0027","rest",2,"reg=civilian,family,worker,rescue",{1,"Tell me something good",2,"I don't have anything",1,"Make something up",2,"Okay, there's a huge feast waiting for us at the next stop, turkey, mashed potatoes",1,"...stop, I'm drooling"}},
{"fw_ld4_topics_a_0028","rest",2,"reg=civilian,family,worker,rescue",{1,"Can I lean on you?",2,"Sure",1,"Thanks",2,"You're heavy",1,"I'm skinny",2,"You're heavy with worry"}},
{"fw_ld4_topics_a_0029","rest",2,"reg=law,swat",{1,"Take ten, I've got the watch",2,"Thanks, boss",1,"Don't thank me, sleep",2,"Wake me if you hear anything",1,"I'll hear everything, that's the problem"}},
{"fw_ld4_topics_a_0030","rest",2,"reg=law,swat",{1,"You got any coffee?",2,"Instant, cold water",1,"That's a crime",2,"In the old days, yes"}},
{"fw_ld4_topics_a_0031","rest",2,"reg=military,elite",{1,"Weapons clean?",2,"Yes, Sergeant",1,"Boots dry?",2,"Yes, Sergeant",1,"Hearts brave?",2,"Working on it, Sergeant"}},
{"fw_ld4_topics_a_0032","rest",2,"reg=military,elite|hour=4,9",{1,"How long can we hold here?",2,"Until dawn, maybe longer",1,"And then?",2,"Then we move, as always"}},
{"fw_ld4_topics_a_0033","rest",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Pass the jerky",2,"Last piece",1,"Split it?",2,"Fine, but I'm taking the bigger half",1,"Of course you are"}},
{"fw_ld4_topics_a_0034","rest",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"What's wrong with you?",2,"Nothing",1,"You've been quiet for an hour",2,"I'm thinking",1,"About what?",2,"About how much I miss real food"}},
{"s10_rest_shoes_off_023","rest",2,"reg=civilian,family,worker|tmp=fresh,seasoned|mood=funny",{1,"If I take my shoes off, they're never going back on",2,"Then leave 'em on",1,"Too late - oh, oh my Lord, that's the best thing that's happened since July"}},
{"s10_rest_knee_gets_up_024","rest",2,"reg=military,swat|tmp=seasoned,veteran|mood=calm",{1,"Take a knee - ten minutes, nobody sits down",2,"What's the difference, Sergeant?",1,"A knee gets back up"}},
{"s10_rest_flightless_bird_025","rest",2,"reg=raider,outlaw,prison|mood=funny",{1,"What're you whittling?",2,"A bird",1,"Looks like a potato",2,"It's a bird that don't fly"}},
{"s10_rest_both_dispatchers_026","rest",2,"reg=law|day=5,300|mood=sad",{1,"You know Dispatch had a thing for you",2,"Which dispatcher?",1,"Both of 'em",2,"Well, nobody told me in time"}},
{"s10_rest_vending_machine_kick_027","rest",2,"reg=family|mood=warm",{1,"We stopped at this exact rest area on the way to Florida in eighty-eight",2,"The one with the vending machines?",1,"Machine ate my dollar, you kicked it and two sodas fell out",2,"Still the best thing I ever did for this family"}},
{"s10_rest_porch_swing_vacation_028","rest",2,"reg=gang,crime|mood=warm|world=building",{1,"Porch swing, my grandma had one just like this in Shelbyville",2,"Scoot over",1,"Two minutes, then we move",2,"Two minutes on a porch swing, that's a whole vacation"}},
{"s10_rest_cold_concrete_029","rest",2,"reg=club|mood=funny",{1,"My back's shot, thirty years on a hardtail",2,"Lay flat on the concrete under the bridge, cold concrete fixes a back",1,"Where'd you hear that?",2,"Every man who ever laid down on concrete"}},
{"s10_rest_slept_yesterday_030","rest",3,"reg=elite|tmp=veteran|mood=calm",{1,"Twenty minutes, two and three sleep, I've got it",2,"When did you sleep?",1,"Yesterday",3,"That doesn't answer me",1,"It's the one you're getting - close your eyes"}},
{"s10_rest_crow_no_rifle_031","rest",2,"reg=prison|hour=9,18|mood=funny",{1,"Lying in the grass and there's not a tower looking at me",2,"There's a crow on the power line looking at you",1,"Crow ain't got a rifle"}},
{"s10_rest_noon_whistle_032","rest",2,"reg=worker|hour=11,13|mood=calm",{1,"Noon, plant whistle would be going right about now",2,"My stomach still hears it",1,"Mine too - pull out whatever you got and let's pretend it's the cafeteria"}},
{"s10_rest_other_side_of_steps_033","rest",2,"reg=civilian,family|tmp=fresh,seasoned|mood=sad",{1,"Sit down here a minute",2,"There's a tricycle in the yard",1,"I see it - sit on the other side of the steps, then, where you can't"}},
{"s10_rest_jacket_not_for_warm_034","rest",2,"reg=rescue,military,law|mood=warm",{1,"She's out cold, sitting straight up on the bucket",2,"Leave her be",1,"Put my jacket over her",2,"It's ninety-one in the shade",1,"It's not for warm"}},
{"s10_rest_ran_out_of_room_035","rest",2,"reg=raider,prison,club|mood=funny",{1,"Who did your tattoo?",2,"Cellmate, guitar string and a ballpoint pen",1,"It says Mother",2,"Was supposed to say Monica, he ran out of arm"}},
{"s10_rest_barn_loft_jinx_036","rest",3,"reg=military|hour=13,23|mood=warm|world=building,rain",{1,"Barn loft - dry hay, rain on a tin roof",2,"Don't say it out loud, you'll jinx it",3,"Somebody's already snoring",2,"That's the Lieutenant - let him"}},
{"s10_rest_pew_counts_037","rest",2,"reg=civilian,family,worker|tmp=seasoned|mood=warm",{1,"Softest pew I ever sat in, and I'm too tired to pray",2,"Sitting counts",1,"Counts? Says who?",2,"My mamaw, she slept through forty years of sermons and swore she heard every word"}},
{"s10_rest_closer_than_morning_038","rest",2,"reg=family|tmp=fresh,seasoned|hour=4,11|mood=warm",{1,"Are we there yet?",2,"We don't have a there yet, bug",1,"Are we closer, then?",2,"We're closer than we were this morning, that's a promise"}},
{"s10_rest_nobody_crumbs_039","rest",3,"reg=gang,crime,raider|mood=angry",{1,"Who ate the crackers?",2,"Wasn't me, man",1,"Nobody's got crumbs all down the front of his shirt",3,"Nobody's also got salt on his lip"}},
{"s10_rest_kick_my_boot_040","rest",3,"reg=law|mood=funny",{1,"Sheriff's asleep with his hat over his face",2,"He does that",1,"How do we know he's asleep and not, you know",2,"Kick his boot",3,"Kick my boot, son, and you're walking home"}},
{"s10_rest_where_we_put_tiny_041","rest",2,"reg=club|day=5,300|mood=sad",{1,"Pull off here a minute",2,"Here? It's a ditch",1,"It's where we put Tiny, I just want to sit a minute",2,"Kill your engine, then, I'll sit too"}},
{"s10_rest_bologna_bait_042","rest",2,"reg=outlaw,civilian,worker|mood=funny|world=water",{1,"Twenty minutes, and I'm putting a line in that creek",2,"With what bait?",1,"Bologna, fish like bologna same as I do",2,"Then you'll be fighting 'em for it"}},
{"s10_rest_good_minute_043","rest",1,"reg=civilian,family,worker|tmp=fresh|mood=calm",{1,"Just sit a minute, nobody's chasing you right now",1,"Right now, right this minute, nobody",1,"Okay, that was a good minute - up you get"}},
{"s10_rest_front_half_044","rest",2,"reg=worker,civilian,military,club|mood=warm",{1,"Last cigarette, half and half",2,"You smoke the front half",1,"Why me?",2,"Front half's better, you carried the heavy bag"}},
{"fw_ld4_topics_a_0035","scavenge",2,"reg=civilian,family,worker,rescue|world=building",{1,"This house is picked clean",2,"Look in the kids' room",1,"Why?",2,"Parents hide stuff in the kids' room, candy, batteries, money",1,"How would you know that?",2,"Because I did, hold on, wait, got it"}},
{"fw_ld4_topics_a_0036","scavenge",2,"reg=civilian,family,worker,rescue",{1,"I feel bad",2,"About what?",1,"Taking someone's stuff",2,"They're not coming back",1,"I know, I know, but it feels like stealing from a grave",2,"It is, in a way, but the living need it more"}},
{"fw_ld4_topics_a_0037","scavenge",2,"reg=civilian,family,worker,rescue|hour=16,5",{1,"Found a can of peaches",2,"Where?",1,"Behind the flour, way in the back",2,"Shake it, is it full?",1,"Full, and the date's okay, we're eating tonight"}},
{"fw_ld4_topics_a_0038","scavenge",2,"reg=civilian,family,worker,rescue",{1,"Look at this, a photo album",2,"Leave it",1,"I can't, they look so happy",2,"Take one picture then, and put it in your pocket",1,"...okay, just one"}},
{"fw_ld4_topics_a_0039","scavenge",2,"reg=civilian,family,worker,rescue|world=building",{1,"Last medicine cabinet I searched was empty",2,"Did you check under the sink?",1,"Nothing but bleach",2,"I hope you didn't mistake that for medicine"}},
{"fw_ld4_topics_a_0040","scavenge",2,"reg=civilian,family,worker,rescue",{1,"I found a diary",2,"Don't read it",1,"One page. That's all I read",2,"It's not ours",1,"Last page. She wrote 'I'm scared' and... that's the last page",2,"Put it back. Easy, now"}},
{"fw_ld4_topics_a_0041","scavenge",2,"reg=civilian,family,worker,rescue",{1,"Whoa, a jar of pickles",2,"Real ones?",1,"Dill, still sealed",2,"Marry me"}},
{"fw_ld4_topics_a_0042","scavenge",2,"reg=civilian,family,worker,rescue",{1,"Everything smells like dust",2,"And mold",1,"And something worse",2,"Let's grab what we can and get out"}},
{"fw_ld4_topics_a_0043","scavenge",2,"reg=law,swat",{1,"Clear the next room",2,"Clear",1,"Anything?",2,"A box of ammo, a first aid kit",1,"Bag them, quietly"}},
{"fw_ld4_topics_a_0044","scavenge",2,"reg=law,swat",{1,"Don't touch the bodies",2,"I wasn't going to",1,"Good, we only search the shelves",2,"What about the safe?",1,"If you can crack it, crack it quietly"}},
{"fw_ld4_topics_a_0045","scavenge",2,"reg=military,elite",{1,"Search and secure",2,"Roger",1,"Anything of use?",2,"Canned goods, batteries, a flashlight",1,"Bag it, move out"}},
{"fw_ld4_topics_a_0046","scavenge",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"Jackpot, look at this",2,"What?",1,"A whole case of whiskey",2,"Is it real or colored water?",1,"Taste it, and tell me"}},
{"fw_ld4_topics_a_0047","scavenge",2,"reg=outlaw,raider,gang,club,crime,prison",{1,"This place has already been hit",2,"By who?",1,"By someone with worse manners than us",2,"What did they leave?",1,"Nothing, which means we're late"}},
{"s10_scav_will_pay_back_023","scavenge",2,"reg=civilian,family|tmp=fresh|day=1,40|mood=funny",{1,"Think I should leave a note",2,"Saying what?",1,"Took two cans of soup and the aspirin - sorry, will pay you back",2,"Put your phone number on it while you're at it"}},
{"s10_scav_gout_shelf_024","scavenge",3,"reg=military,law|mood=funny",{1,"Behind the pharmacy counter - what's left?",2,"Cough syrup, foot powder, and a whole shelf of something for gout",1,"Anybody got gout?",3,"Not yet - give me time, and all this canned ham"}},
{"s10_scav_bigger_x_025","scavenge",3,"reg=raider|tmp=predator|mood=funny|world=door",{1,"House has an X on the door, somebody's been through",2,"Whose X?",1,"Red paint, that's the Irvington crew",3,"Then paint our X over theirs - bigger"}},
{"s10_scav_announce_anyway_026","scavenge",2,"reg=law|role=law_deputy,law_sheriff|mood=calm",{1,"Sheriff's office! Anybody in the house?",2,"Why do you still announce?",1,"'Cause if a man's in there with a shotgun, I want him knowing it's us before he finds out the hard way"}},
{"s10_scav_bear_carries_027","scavenge",2,"reg=family|mood=warm",{1,"One toy each, something small you can carry",2,"Can I take the big bear?",1,"That bear's bigger than you are",2,"I'll carry him, and he'll carry my stuff"}},
{"s10_scav_eat_a_necklace_028","scavenge",2,"reg=gang,crime|mood=funny",{1,"Jewelry store's standing wide open",2,"Grocery's right next door",1,"Grocery's picked clean, jewelry store ain't",2,"'Cause you can't eat a necklace, whole county figured that out but you"}},
{"s10_scav_parts_store_pine_029","scavenge",2,"reg=club|mood=funny|world=trees",{1,"Parts store, plugs, filters, chain lube, anything with a part number goes in the bag",2,"Air fresheners?",1,"Take the pine trees, clubhouse smells like the inside of a boot"}},
{"s10_scav_nitrous_leave_it_030","scavenge",3,"reg=elite|tmp=veteran|mood=funny",{1,"Dentist office, lidocaine, gauze, suture kits",2,"Nitrous tank in the back room",1,"Leave the tank",3,"Could be useful",1,"Could be - leave it"}},
{"s10_scav_evidence_room_031","scavenge",2,"reg=prison|mood=funny|world=door",{1,"Evidence room door's hanging open",2,"I know what's in there, some of it's mine",1,"Then go get your stuff back - I'll wait"}},
{"s10_scav_sixty_nine_cents_032","scavenge",2,"reg=worker,civilian|mood=funny",{1,"Hardware store, nails still in the bins",2,"Sign on the scale still says sixty-nine cents a pound",1,"Weigh 'em anyway, I want to know what I stole"}},
{"s10_scav_fire_axe_keypad_033","scavenge",2,"reg=rescue|role=rescue_medical|mood=funny|world=door",{1,"Supply room is the third door past the nurses' station - Code's four-one-one-two",2,"Power's out - Keypad's dead",1,"Then it's the fire axe, I've wanted to do that for eleven years"}},
{"s10_scav_close_the_door_034","scavenge",2,"reg=civilian,worker,family,law|tmp=seasoned|day=5,300|mood=grim|world=door,building",{1,"There's somebody in the bathtub",2,"Turned?",1,"No, empty pill bottle and a note on the sink",2,"Leave the note, check the cabinet - close the door on your way out"}},
{"s10_scav_carters_cereal_035","scavenge",2,"reg=family,civilian|role=family_youth,civilian_man,civilian_woman|tmp=fresh|mood=sad|world=door,building",{1,"This is the Carters' house, I slept over here a hundred times",2,"Then you know where they keep things",1,"Pantry's behind the folding door - Mrs. Carter hid the good cereal up on top so Josh couldn't reach"}},
