{"s10_scav_recruiting_office_037","scavenge",3,"reg=military|day=5,300|mood=funny|world=door",{1,"Recruiting office on Dixie Highway, posters, pamphlets, a cardboard soldier by the door",2,"Anything we can use?",1,"Coffee maker, a box of pens, and forty T-shirts with the slogan on the front",3,"Take the shirts, we're out of undershirts",1,"So now all of us walk around in recruiting shirts - poster boys for the whole county"}},
{"s10_scav_one_pair_run_038","scavenge",2,"reg=gang,civilian|mood=calm",{1,"Shoe store, nobody takes more than one pair",2,"One pair? It's a whole store",1,"One pair you can run in, not a pair to look at"}},
{"s10_scav_factory_whiskey_039","scavenge",2,"reg=outlaw|mood=funny",{1,"You'd pick homemade whiskey over a liquor store's top shelf?",2,"Store-bought, tastes like a factory",1,"I'd rather know what was in it than argue about where it came from"}},
